import{_ as t,c as a,o as r,ag as n}from"./chunks/framework.ARG558ZT.js";const u=JSON.parse('{"title":"Frontend practice sequence","description":"","frontmatter":{},"headers":[],"relativePath":"practice/frontend/index.md","filePath":"practice/frontend/index.md"}'),s={name:"practice/frontend/index.md"};function i(c,e,d,o,l,p){return r(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="frontend-practice-sequence" tabindex="-1">Frontend practice sequence <a class="header-anchor" href="#frontend-practice-sequence" aria-label="Permalink to “Frontend practice sequence”">​</a></h1><p><strong>Every stage is outstanding learner practice.</strong> Reuse <a href="./../frontend-project.html">P-328, P-329 and P-330</a>; these smaller increments make the existing management-screen specification achievable. A public two-course corpus reduces setup in F01–F05. F06 introduces two users and server authority deliberately; a public fixture cannot establish authorization.</p><h2 id="staged-sequence" tabindex="-1">Staged sequence <a class="header-anchor" href="#staged-sequence" aria-label="Permalink to “Staged sequence”">​</a></h2><table tabindex="0"><thead><tr><th>Stage</th><th>Prerequisites and scope</th><th>Observable result</th></tr></thead><tbody><tr><td><a href="./f01-document.html">F01 — document and interaction</a></td><td>Basic HTML; native public search and one dialog</td><td>No-JS task, names, keyboard/focus and recovery work</td></tr><tr><td><a href="./f02-layout.html">F02 — responsive CSS</a></td><td>F01; layout/cascade/theme</td><td>Long content and focus remain usable at narrow/wide widths</td></tr><tr><td><a href="./f03-javascript.html">F03 — JavaScript lifetime</a></td><td>Functions, closures, promises; owned search</td><td>Late work cannot overwrite current intent; cleanup releases owners</td></tr><tr><td><a href="./f04-typescript.html">F04 — typed boundary</a></td><td>F03; strict TS and runtime parsing</td><td>Invalid payloads reject; impossible states fail compile</td></tr><tr><td><a href="./f05-react.html">F05 — React ownership</a></td><td>F01–F04; P-329</td><td>Stable drafts, truthful forms, races and effect cleanup</td></tr><tr><td><a href="./f06-next.html">F06 — Next and contracts</a></td><td>F05 plus HTTP and server authorization; P-328/P-330</td><td>Narrow client boundary, defined freshness, authorized mutation</td></tr></tbody></table><p>Each stage records source revision, environment, expected/actual outcomes, one failure→correction→retest and explicit unperformed checks. Do not duplicate the full application per topic. Keep smaller counterexamples isolated from the working version.</p><h2 id="extracted-lesson-requirements" tabindex="-1">Extracted lesson requirements <a class="header-anchor" href="#extracted-lesson-requirements" aria-label="Permalink to “Extracted lesson requirements”">​</a></h2><p>The linked topic indexes list the original exercises moved out of textbook paragraphs. They refine the same projects; they do not require a new application per page.</p><ul><li><a href="./a11y/">HTML/accessibility cases</a></li><li><a href="./css/">CSS cases</a></li><li><a href="./general_es6/">JavaScript cases</a></li><li><a href="./typescript/">TypeScript cases</a></li><li><a href="./react/">React and Next cases</a></li></ul><p><a href="./../../workbench/frontend/">Reference workbench</a> supplies examples, not completed learner deliverables. <a href="./../../frontend/verification.html">Author verification</a> is a separate evidence ledger.</p>',9)])])}const f=t(s,[["render",i]]);export{u as __pageData,f as default};
